def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    names = sorted(packages)
    positions = {name: i for i, name in enumerate(names)}

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    required = set(roots)

    def within(version, ranges):
        return all(low <= version <= high for low, high in ranges)

    def search(index, assignment, current_constraints, current_required):
        if index == len(names):
            installed = {name for name, version in assignment.items() if version is not None}
            if installed == current_required:
                return {name: assignment[name] for name in names if assignment[name] is not None}
            return None

        name = names[index]
        ranges = current_constraints.get(name, [])
        rows = [row for row in choose(packages[name])
                if row['version'] not in blocked.get(name, [])
                and within(row['version'], ranges)]

        options = list(rows)
        if name not in current_required:
            options.append(None)

        for row in options:
            next_assignment = assignment.copy()
            next_constraints = {key: value.copy() for key, value in current_constraints.items()}
            next_required = current_required.copy()
            if row is None:
                next_assignment[name] = None
            else:
                version = row['version']
                next_assignment[name] = version
                valid = True
                for dep in row.get('deps', []):
                    target = dep['name']
                    if target not in packages:
                        valid = False
                        break
                    low, high = dep['min'], dep['max']
                    next_constraints.setdefault(target, []).append((low, high))
                    next_required.add(target)
                    if positions[target] <= index:
                        target_version = next_assignment.get(target)
                        if target_version is None or not (low <= target_version <= high):
                            valid = False
                            break
                if not valid:
                    continue

            result = search(index + 1, next_assignment, next_constraints, next_required)
            if result is not None:
                return result
        return None

    versions = search(0, {}, constraints, required)
    if versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': versions}
